S = "Hakeem Force Academy"
QS = [
(S, "Who was the second Governor General of Pakistan?", ["Malik Ghulam Muhammad", "Khawaja Nazimuddin", "Iskander Mirza", "Liaquat Ali Khan"], 1,
 "After the death of Quaid-e-Azam in September 1948, Khawaja Nazimuddin became Governor General of Pakistan. He held the post until 1951.",
 "Nazimuddin was followed as Governor General by Malik Ghulam Muhammad in 1951.", 11),
(S, "Who was the ruler of Pakistan after Yahya Khan?", ["Zia ul Haq", "Ayub Khan", "Zulfikar Ali Bhutto", "Tikka Khan"], 2,
 "Yahya Khan handed over power in December 1971 after the fall of Dhaka, and Zulfikar Ali Bhutto became President and Chief Martial Law Administrator.",
 "Bhutto later became Prime Minister under the 1973 Constitution.", 3),
(S, "Who took over as martial law administrator after Ayub Khan resigned in 1969?", ["Tikka Khan", "Yahya Khan", "Zia ul Haq", "Iskander Mirza"], 1,
 "Ayub Khan handed power to the army chief General Yahya Khan in March 1969, who imposed martial law.",
 "Yahya Khan ruled until December 1971.", 2),
(S, "Who was the first Commander-in-Chief of the Pakistan Army?", ["General Ayub Khan", "General Tikka Khan", "General Sir Frank Messervy", "General Sir Douglas Gracey"], 2,
 "General Sir Frank Messervy was the first Commander-in-Chief of the Pakistan Army from August 1947 to February 1948.",
 "Douglas Gracey succeeded him, and Ayub Khan was the first native Pakistani Commander-in-Chief in 1951.", 4),
(S, "Who was the first captain of the Pakistan cricket team?", ["Fazal Mahmood", "Abdul Hafeez Kardar", "Imran Khan", "Hanif Mohammad"], 1,
 "Abdul Hafeez Kardar captained Pakistan in its first Test series in India in 1952.",
 "Under Kardar, Pakistan won its first Test on English soil at The Oval in 1954.", 2),
(S, "Who was the first Chief Justice of Pakistan?", ["Muhammad Munir", "Sir Abdul Rashid", "Mian Abdul Rashid", "Sheikh Abdur Rahman"], 1,
 "Sir Abdul Rashid became the first Chief Justice of the Federal Court of Pakistan in 1949.",
 "Muhammad Munir succeeded him as Chief Justice in 1954.", 8),
(S, "Who was the first Mughal emperor of India?", ["Humayun", "Akbar", "Babur", "Sher Shah Suri"], 2,
 "Babur founded the Mughal Empire after defeating Ibrahim Lodhi at the First Battle of Panipat in 1526.",
 "Sher Shah Suri was not a Mughal; he briefly defeated Humayun.", 3),
(S, "Who was the first Foreign Minister of Pakistan?", ["Sir Zafarullah Khan", "Liaquat Ali Khan", "Hussain Shaheed Suhrawardy", "Muhammad Ali Bogra"], 0,
 "Sir Muhammad Zafarullah Khan was appointed the first Foreign Minister of Pakistan in 1947 and served until 1954.",
 "He later served as a judge and President of the International Court of Justice.", 12),
(S, "Who was the first Governor General of independent India in 1947?", ["Lord Mountbatten", "Lord Wavell", "C. Rajagopalachari", "Lord Curzon"], 0,
 "Lord Mountbatten became Governor General of the Dominion of India on 15 August 1947.",
 "Sources differ because Warren Hastings and William Bentinck are also called the first Governor General in earlier British India, but for 1947 it is Mountbatten.", 9),
(S, "Who was the first Governor General of Pakistan?", ["Liaquat Ali Khan", "Khawaja Nazimuddin", "Muhammad Ali Jinnah", "Iskander Mirza"], 2,
 "Muhammad Ali Jinnah took the oath as the first Governor General of Pakistan on 15 August 1947.",
 "He held the office until his death on 11 September 1948.", 2),
(S, "Who was the last Governor General of Pakistan?", ["Malik Ghulam Muhammad", "Iskander Mirza", "Ayub Khan", "Khawaja Nazimuddin"], 1,
 "Iskander Mirza was the last Governor General and became the first President when the 1956 Constitution came into force.",
 "Pakistan became a republic on 23 March 1956.", 2),
(S, "Who was the first man to embrace Islam?", ["Hazrat Ali (RA)", "Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Uthman (RA)"], 2,
 "Hazrat Abu Bakr Siddique (RA) is regarded as the first adult free man to accept Islam.",
 "Sources differ: Hazrat Ali (RA) is regarded as the first child to accept Islam.", 3),
(S, "Who was the first to translate the Holy Quran into Urdu?", ["Shah Abdul Qadir Dehlvi", "Shah Waliullah", "Sir Syed Ahmad Khan", "Maulana Ashraf Ali Thanvi"], 0,
 "Shah Abdul Qadir Dehlvi produced the first idiomatic Urdu translation, Mudih-ul-Quran, in the 1790s.",
 "Sources differ: his brother Shah Rafiuddin made an earlier literal Urdu translation, but most Pakistani textbooks credit Shah Abdul Qadir.", 2),
(S, "Who was the first woman martyred in Islam?", ["Hazrat Khadija (RA)", "Hazrat Sumayyah (RA)", "Hazrat Fatima (RA)", "Hazrat Ayesha (RA)"], 1,
 "Hazrat Sumayyah bint Khayyat (RA) was killed by Abu Jahl for refusing to give up Islam.",
 "Her husband Hazrat Yasir (RA) was also martyred.", 3),
(S, "Who was the first woman Prime Minister of a Muslim country?", ["Benazir Bhutto", "Khaleda Zia", "Tansu Ciller", "Sheikh Hasina"], 0,
 "Benazir Bhutto became Prime Minister of Pakistan in 1988, the first woman to head a Muslim country's government.",
 "She was Prime Minister twice, in 1988-90 and 1993-96.", 2),
(S, "Who was the world's first woman Prime Minister?", ["Indira Gandhi", "Golda Meir", "Sirimavo Bandaranaike", "Margaret Thatcher"], 2,
 "Sirimavo Bandaranaike of Sri Lanka became the world's first woman Prime Minister in 1960.",
 "Indira Gandhi became India's Prime Minister in 1966.", 4),
(S, "Who was the first Pakistani to climb Mount Everest?", ["Hassan Sadpara", "Nazir Sabir", "Ashraf Aman", "Samina Baig"], 1,
 "Nazir Sabir reached the summit of Mount Everest in 1999 as the first Pakistani to do so.",
 "Samina Baig became the first Pakistani woman to climb Everest in 2013.", 5),
(S, "Who was the first person in space?", ["Neil Armstrong", "Yuri Gagarin", "Alan Shepard", "Valentina Tereshkova"], 1,
 "Soviet cosmonaut Yuri Gagarin orbited the Earth aboard Vostok 1 on 12 April 1961.",
 "Valentina Tereshkova became the first woman in space in 1963.", 3),
(S, "Who was the first Prime Minister of Pakistan?", ["Khawaja Nazimuddin", "Liaquat Ali Khan", "Muhammad Ali Bogra", "Chaudhry Muhammad Ali"], 1,
 "Liaquat Ali Khan became the first Prime Minister of Pakistan on 15 August 1947.",
 "He was assassinated at Rawalpindi on 16 October 1951.", 17),
(S, "Who was the first president of the All India Muslim League?", ["Quaid-e-Azam Muhammad Ali Jinnah", "Sir Aga Khan III", "Nawab Salimullah", "Allama Iqbal"], 1,
 "Sir Sultan Muhammad Shah Aga Khan III was the first president of the All India Muslim League, founded in Dhaka in 1906.",
 "The League was founded at Dhaka during the All India Muhammadan Educational Conference.", 7),
(S, "Who was the first Prime Minister of Pakistan to visit America?", ["Khawaja Nazimuddin", "Liaquat Ali Khan", "Muhammad Ali Bogra", "Huseyn Shaheed Suhrawardy"], 1,
 "Liaquat Ali Khan visited the United States in May 1950, the first Pakistani Prime Minister to do so.",
 "His visit came after he chose Washington over an invitation from Moscow.", 5),
(S, "Who was the first wife of the Holy Prophet Muhammad (PBUH)?", ["Hazrat Ayesha (RA)", "Hazrat Khadija (RA)", "Hazrat Hafsa (RA)", "Hazrat Sawda (RA)"], 1,
 "Hazrat Khadija bint Khuwaylid (RA) married the Prophet (PBUH) about 15 years before the first revelation.",
 "The Prophet (PBUH) did not marry again during her lifetime.", 17),
(S, "Who was the first woman to accept Islam?", ["Hazrat Ayesha (RA)", "Hazrat Fatima (RA)", "Hazrat Sumayyah (RA)", "Hazrat Khadija (RA)"], 3,
 "Hazrat Khadija (RA) believed in the Prophet (PBUH) immediately after the first revelation and was the first person to accept Islam.",
 "She is known as Khadija tul Kubra.", 4),
(S, "Who was the founder of the Indian National Congress?", ["Dadabhai Naoroji", "A. O. Hume", "Gopal Krishna Gokhale", "Surendranath Banerjee"], 1,
 "Allan Octavian Hume, a retired British civil servant, founded the Indian National Congress in 1885.",
 "Its first session in Bombay was presided over by W. C. Bonnerjee.", 2),
(S, "Who was the founder of the DAWN newspaper?", ["Liaquat Ali Khan", "Quaid-e-Azam Muhammad Ali Jinnah", "Allama Iqbal", "Maulana Zafar Ali Khan"], 1,
 "Muhammad Ali Jinnah founded Dawn in Delhi in 1941 as a voice of the Muslim League.",
 "Dawn moved to Karachi after the creation of Pakistan.", 2),
(S, "Who was the last Mughal emperor of India?", ["Bahadur Shah Zafar", "Aurangzeb Alamgir", "Shah Alam II", "Muhammad Shah"], 0,
 "Bahadur Shah Zafar was deposed by the British after the War of Independence of 1857.",
 "He was exiled to Rangoon, where he died in 1862.", 2),
(S, "Who was the last prophet sent to Bani Israel?", ["Hazrat Musa (AS)", "Hazrat Dawood (AS)", "Hazrat Isa (AS)", "Hazrat Yahya (AS)"], 2,
 "Hazrat Isa (AS) was the last prophet sent to Bani Israel before Prophet Muhammad (PBUH).",
 "Hazrat Isa (AS) was given the Injeel.", 2),
(S, "Who was the commander of the Quraish army in the Battle of Badr?", ["Abu Sufyan", "Abu Jahl", "Khalid bin Waleed", "Ikrimah"], 1,
 "Abu Jahl (Amr bin Hisham) led the Quraish army at Badr in 2 AH and was killed in the battle.",
 "Abu Sufyan led the trade caravan that the Quraish army came to protect.", 2),
(S, "Who won the world amateur snooker championship in 1994 for Pakistan?", ["Muhammad Yousaf", "Muhammad Asif", "Muhammad Sajjad", "Naveed Alam"], 0,
 "Muhammad Yousaf won the IBSF World Amateur Snooker Championship in 1994.",
 "Muhammad Asif later won the same title in 2012.", 2),
(S, "Who was the President of the first Constituent Assembly of Pakistan?", ["Liaquat Ali Khan", "Maulvi Tamizuddin Khan", "Muhammad Ali Jinnah", "Khawaja Nazimuddin"], 2,
 "Quaid-e-Azam Muhammad Ali Jinnah was elected President of the Constituent Assembly on 11 August 1947.",
 "Maulvi Tamizuddin Khan later served as its Speaker.", 4),
(S, "Who was the second caliph of Islam?", ["Hazrat Abu Bakr (RA)", "Hazrat Umar Farooq (RA)", "Hazrat Uthman (RA)", "Hazrat Ali (RA)"], 1,
 "Hazrat Umar Farooq (RA) became caliph in 634 CE after Hazrat Abu Bakr (RA).",
 "His caliphate lasted about ten years.", 2),
(S, "Who among the following was a son-in-law of the Holy Prophet (PBUH)?", ["Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Umar (RA)", "Hazrat Hamza (RA)"], 1,
 "Hazrat Ali (RA) married the Prophet's daughter Hazrat Fatima (RA).",
 "Hazrat Uthman (RA) was also a son-in-law, having married Hazrat Ruqayyah and later Hazrat Umm Kulthum (RA).", 3),
(S, "Who accompanied the Prophet (PBUH) during the migration to Madinah?", ["Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Bilal (RA)"], 1,
 "Hazrat Abu Bakr (RA) travelled with the Prophet (PBUH) and they hid in the cave of Thawr.",
 "Hazrat Ali (RA) stayed behind in Makkah to return the trusts kept with the Prophet (PBUH).", 3),
(S, "Which people lived at Khyber at the time of the Prophet (PBUH)?", ["Christians", "Jews", "Quraish", "Persians"], 1,
 "Khyber was a fortified oasis inhabited mainly by Jewish tribes, and the Muslims conquered it in 7 AH.",
 "Hazrat Ali (RA) is famous for his role in the conquest of the fort of Khyber.", 2),
(S, "Which team won the cricket World Cup in 1999?", ["Pakistan", "Australia", "South Africa", "Sri Lanka"], 1,
 "Australia beat Pakistan by eight wickets in the 1999 final at Lord's.",
 "Pakistan was the runner-up in 1999 and champion in 1992.", 4),
(S, "Who wrote Das Kapital?", ["Friedrich Engels", "Karl Marx", "Adam Smith", "Vladimir Lenin"], 1,
 "Karl Marx wrote Das Kapital, whose first volume appeared in 1867.",
 "Engels edited the second and third volumes after Marx died.", 3),
(S, "Who wrote the Punjabi romance Heer Ranjha?", ["Waris Shah", "Bulleh Shah", "Fazal Shah", "Baba Farid"], 0,
 "Waris Shah wrote the best known version of Heer in 1766.",
 "Earlier versions of the story were written by Damodar Gulati.", 11),
(S, "Who wrote the novel Raja Gidh?", ["Ashfaq Ahmed", "Mumtaz Mufti", "Bano Qudsia", "Qurratulain Hyder"], 2,
 "Bano Qudsia wrote Raja Gidh, a novel about the concept of haram and halal food and its effect on the mind.",
 "She was married to the writer Ashfaq Ahmed.", 9),
(S, "Who wrote The Reconstruction of Religious Thought in Islam?", ["Maulana Maududi", "Allama Muhammad Iqbal", "Sir Syed Ahmad Khan", "Maulana Muhammad Ali Jauhar"], 1,
 "Allama Iqbal wrote this book, which is based on his lectures delivered in 1928-29.",
 "It was first published in 1930 and expanded in 1934.", 5),
(S, "Who wrote Shah Jo Risalo?", ["Sachal Sarmast", "Shah Abdul Latif Bhittai", "Bulleh Shah", "Khwaja Ghulam Farid"], 1,
 "Shah Abdul Latif Bhittai composed the Sindhi poetry collection Shah Jo Risalo.",
 "His shrine is at Bhit Shah in Sindh.", 3),
(S, "Who was the brother of Hazrat Khalid bin Waleed (RA)?", ["Walid bin Walid", "Abu Jahl", "Amr bin Al-Aas", "Ikrimah bin Abi Jahl"], 0,
 "Walid bin Walid (RA) was the brother of Khalid bin Waleed (RA) and accepted Islam before him.",
 "Their father Waleed bin Mughirah was a leader of the Banu Makhzum of Quraish.", 6),
]
